import SchemaBuilder from '@pothos/core';

const builder = new SchemaBuilder({});

const VehicleType = {
  sedan: 'SEDAN',
  suv: 'SUV',
  truck: 'TRUCK',
  motorcycle: 'MOTORCYCLE',
} as const;

const VehicleTypeEnum = builder.enumType('VehicleType', {
  values: Object.values(VehicleType),
});

builder.queryType({
  fields: (t) => ({
    vehicle: t.field({
      type: VehicleTypeEnum,
      args: { value: t.arg({ type: VehicleTypeEnum, required: true }) },
      resolve: (_parent, { value }) => value,
    }),
    internalValue: t.string({
      args: { value: t.arg({ type: VehicleTypeEnum, required: true }) },
      resolve: (_parent, { value }) => value,
    }),
  }),
});
export const schema = builder.toSchema();

defaultQuery:
query VariantValues {
  vehicle(value: SEDAN)
  internalValue(value: SEDAN)
}

